@push('scripts')<script>
document.addEventListener('hris:ready',()=>{
const windowForm = document.querySelector('#office-punch-window-form'), windowTable = document.querySelector('#office-punch-windows');
if (windowForm) {
    HRIS.bindForm(windowForm, {success: () => {windowTable.table.load(); window.dispatchEvent(new Event('attendance:office-access-changed'));}});
    windowTable.addEventListener('table:action', async ({detail: {row}}) => {
        if (row.revoked_at || !await HRIS.confirm('Revoke this office punch access window?')) return;
        try { HRIS.feedback((await HRIS.request(`/attendance/office-punch-windows/${row.id}/revoke`, {method: 'POST'})).message); windowTable.table.load(); window.dispatchEvent(new Event('attendance:office-access-changed')); }
        catch (error) { HRIS.feedback(error.message, true); }
    });
}
const employee={{ $employee->id }},table=document.querySelector('#attendance-table'),raw=document.querySelector('#raw-table'),from=document.querySelector('#attendance-from'),to=document.querySelector('#attendance-to');function range(){return{from:from.value,to:to.value}}function refresh(){table.table.load();raw.table.load()}function links(){const params=new URLSearchParams(range());document.querySelector('#attendance-print').href=`/attendance/${employee}/report?${params}`;document.querySelector('#attendance-csv').href=`/attendance/${employee}/report?${params}&format=csv`;raw.table.params=new URLSearchParams(range());raw.table.page=1;raw.table.load()}links();[from,to].forEach(input=>input.addEventListener('change',links));table.addEventListener('table:loaded',({detail})=>document.querySelectorAll('[data-total]').forEach(element=>element.textContent=detail.summary?.[element.dataset.total]??0));for(const [id,wfh]of[['clock-wfh',true]])document.getElementById(id)?.addEventListener('click',async event=>{const button=event.currentTarget;button.disabled=true;try{HRIS.feedback((await HRIS.request('/attendance/clock',{method:'POST',body:{wfh}})).message);raw.table.load()}catch(error){HRIS.feedback(error.message,true)}finally{button.disabled=false}});
 window.addEventListener('attendance:punch-recorded',()=>raw.table.load());
 const form=document.querySelector('#correction-form');if(form){HRIS.bindForm(form,{success:refresh});document.querySelector('#create-correction').onclick=()=>{HRIS.fillForm(form,{});HRIS.openModal('correction-modal')};HRIS.bindForm(document.querySelector('#rebuild-form'),{prepare:body=>Object.assign(body,range()),success:refresh});const remarks=document.querySelector('#remarks-form');HRIS.bindForm(remarks);document.querySelector('#open-remarks').onclick=async()=>{try{const coverage=from.value;const current=await HRIS.request(`/attendance/${employee}/remarks?coverage=${coverage}`);HRIS.fillForm(remarks,{coverage,fc_absence:0,...(current||{})});HRIS.openModal('remarks-modal')}catch(error){HRIS.feedback(error.message,true)}}}
 table.addEventListener('table:action',({detail:{action,row}})=>{if(action==='edit'){HRIS.fillForm(form,row);HRIS.openModal('correction-modal')}if(action==='history'){const revisions=document.querySelector('#revisions-table');revisions.dataset.endpoint=`/attendance/${employee}/revisions/${row.id}`;revisions.table.page=1;revisions.table.load();HRIS.openModal('revisions-modal')}});document.querySelector('#revisions-table').addEventListener('table:action',({detail:{row}})=>HRIS.showDetails('Calculation revision',{reason:row.reason,before:row.before,after:row.after}));
});
</script>@endpush
